#include "voicelink/controller.hpp"
#include "voice_wifi_adapter.hpp"
#include <cstdio>
#include <cstring>
#include <ctime>
#include <unistd.h>

#ifdef K7VOICE_NATIVE_ORT_ADD
extern "C" int k7_ort_add_probe(void);
