}
static uint32_t pad_input(void *ctx) { return rd(ctx, GPIO4 + 0x70); }

static int abs_read(void *ctx, uintptr_t addr, uint32_t *value)
{
  *value = rd(ctx, addr);
  return 0;
}
static int abs_write(void *ctx, uintptr_t addr, uint32_t value)
{
