    f.ctl.ingest("你好，openvela");
    f.wifi.scanResult = {ScanStatus::Scanning, {}, 0, 501};
    f.ctl.poll();
    assert(f.ctl.context().state == State::ScanningWifi);
    f.wifi.scanResult = {ScanStatus::Ready, {{"Foreign", -1, false}}, 0, 502};
