#pragma once

#include "voicelink/types.hpp"

#include <optional>
#include <string>
#include <vector>

namespace voicelink {

std::string normalize(const std::string& text);
// 唤醒判定：text 折叠（normalize + 去 ASCII 标点）后，与任一候选词全等，
