    assert(wifi.scans == 0);
    ctl.ingest("你好，openvela");
    assert(ctl.context().state == State::ScanningWifi);
    ctl.poll();
    assert(ctl.context().state == State::WaitingNetworkChoice);
    assert(ctl.context().candidates.size() == 2);
