## work-in-progress/parallel-dns-client-sol/include/vv_dns_client.h
#ifndef VV_DNS_CLIENT_H
#define VV_DNS_CLIENT_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

#define VV_DNS_HOSTNAME_MAX 128u
#define VV_DNS_ATTEMPTS_MAX 3u

enum vv_dns_status
{
  VV_DNS_OK = 0,
  VV_DNS_INVALID_ARGUMENT = -1,
  VV_DNS_DEADLINE_EXCEEDED = -2,
  VV_DNS_TEMPORARY_FAILURE = -3,
  VV_DNS_NOT_FOUND = -4,
  VV_DNS_NO_IPV4_ADDRESS = -5,
  VV_DNS_SYSTEM_FAILURE = -6,
  VV_DNS_CANCELLED = -7
};

struct vv_dns_policy
{
  uint32_t deadline_ms;
  uint32_t retry_backoff_ms;
  unsigned int max_attempts;
};

struct vv_dns_result
{
  uint32_t ipv4_be;
  unsigned int attempts;
  int backend_code;
};

struct vv_dns_backend
{
  void *context;
  enum vv_dns_status (*resolve_ipv4)(void *context,
                                     const char *hostname,
                                     uint32_t timeout_ms,
                                     uint32_t *ipv4_be,
                                     int *backend_code);
  uint64_t (*now_ms)(void *context);
  void (*sleep_ms)(void *context, uint32_t delay_ms);
  bool (*cancelled)(void *context);
};

enum vv_dns_status vv_dns_resolve_ipv4(const char *hostname,
                                       const struct vv_dns_policy *policy,
                                       const struct vv_dns_backend *backend,
                                       struct vv_dns_result *result);

const char *vv_dns_status_name(enum vv_dns_status status);

#ifdef __cplusplus
}
#endif

#endif

## work-in-progress/parallel-dns-client-sol/src/vv_dns_client.c
#include "vv_dns_client.h"

#include <string.h>

static bool vv_dns_hostname_valid(const char *hostname)
{
  size_t length = 0;
  size_t label_length = 0;
  size_t i;

  if (hostname == NULL)
    {
      return false;
    }

  while (length <= VV_DNS_HOSTNAME_MAX && hostname[length] != '\0')
    {
      ++length;
    }

  if (length == 0 || length > VV_DNS_HOSTNAME_MAX)
    {
      return false;
    }

  for (i = 0; i < length; ++i)
    {
      unsigned char c = (unsigned char)hostname[i];
      if (c == '.')
        {
          if (label_length == 0 || hostname[i - 1] == '-')
            {
              return false;
            }

          label_length = 0;
          continue;
        }

      if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
            (c >= '0' && c <= '9') || c == '-'))
        {
          return false;
        }

      if (label_length == 0 && c == '-')
        {
          return false;
        }

      if (++label_length > 63u)
        {
          return false;
        }
    }

  return label_length != 0 && hostname[length - 1] != '-';
}

static bool vv_dns_is_cancelled(const struct vv_dns_backend *backend)
{
  return backend->cancelled != NULL && backend->cancelled(backend->context);
}

enum vv_dns_status vv_dns_resolve_ipv4(const char *hostname,
                                       const struct vv_dns_policy *policy,
                                       const struct vv_dns_backend *backend,
                                       struct vv_dns_result *result)
{
  uint64_t started;
  unsigned int attempt;
  enum vv_dns_status status = VV_DNS_SYSTEM_FAILURE;

  if (result != NULL)
    {
      memset(result, 0, sizeof(*result));
    }

  if (!vv_dns_hostname_valid(hostname) || policy == NULL || backend == NULL ||
      result == NULL || backend->resolve_ipv4 == NULL || backend->now_ms == NULL ||
      policy->deadline_ms == 0 || policy->max_attempts == 0 ||
      policy->max_attempts > VV_DNS_ATTEMPTS_MAX)
    {
      return VV_DNS_INVALID_ARGUMENT;
    }

  started = backend->now_ms(backend->context);
  for (attempt = 0; attempt < policy->max_attempts; ++attempt)
    {
      uint64_t now;
      uint64_t elapsed;
      uint32_t remaining;

      if (vv_dns_is_cancelled(backend))
        {
          return VV_DNS_CANCELLED;
        }

      now = backend->now_ms(backend->context);
      elapsed = now >= started ? now - started : policy->deadline_ms;
      if (elapsed >= policy->deadline_ms)
        {
          return VV_DNS_DEADLINE_EXCEEDED;
        }

      remaining = policy->deadline_ms - (uint32_t)elapsed;
      result->attempts = attempt + 1u;
      result->backend_code = 0;
      status = backend->resolve_ipv4(backend->context, hostname, remaining,
                                     &result->ipv4_be,
                                     &result->backend_code);

      now = backend->now_ms(backend->context);
      elapsed = now >= started ? now - started : policy->deadline_ms;
      if (elapsed >= policy->deadline_ms)
        {
          result->ipv4_be = 0;
          return VV_DNS_DEADLINE_EXCEEDED;
        }

      if (vv_dns_is_cancelled(backend))
        {
          result->ipv4_be = 0;
          return VV_DNS_CANCELLED;
        }

      if (status == VV_DNS_OK)
        {
          if (result->ipv4_be == 0)
            {
              return VV_DNS_NO_IPV4_ADDRESS;
            }

          return VV_DNS_OK;
        }

      result->ipv4_be = 0;
      if (status != VV_DNS_TEMPORARY_FAILURE ||
          attempt + 1u == policy->max_attempts)
        {
          return status;
        }

      if (policy->retry_backoff_ms > 0)
        {
          uint32_t sleep_ms;
          now = backend->now_ms(backend->context);
          elapsed = now >= started ? now - started : policy->deadline_ms;
          if (elapsed >= policy->deadline_ms)
            {
              return VV_DNS_DEADLINE_EXCEEDED;
            }

          remaining = policy->deadline_ms - (uint32_t)elapsed;
          sleep_ms = policy->retry_backoff_ms < remaining
                     ? policy->retry_backoff_ms : remaining;
          if (backend->sleep_ms != NULL)
            {
              backend->sleep_ms(backend->context, sleep_ms);
            }
        }
    }

  return status;
}

const char *vv_dns_status_name(enum vv_dns_status status)
{
  switch (status)
    {
      case VV_DNS_OK: return "ok";
      case VV_DNS_INVALID_ARGUMENT: return "invalid_argument";
      case VV_DNS_DEADLINE_EXCEEDED: return "deadline_exceeded";
      case VV_DNS_TEMPORARY_FAILURE: return "temporary_failure";
      case VV_DNS_NOT_FOUND: return "not_found";
      case VV_DNS_NO_IPV4_ADDRESS: return "no_ipv4_address";
      case VV_DNS_SYSTEM_FAILURE: return "system_failure";
      case VV_DNS_CANCELLED: return "cancelled";
      default: return "unknown";
    }
}

## work-in-progress/parallel-dns-client-sol/src/vv_dns_nuttx.c
#include "vv_dns_nuttx.h"

#include <errno.h>
#include <netdb.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <sys/socket.h>
#include <time.h>
#include <unistd.h>

#include <netinet/in.h>

#ifndef CONFIG_NETDB_DNSCLIENT_SEND_TIMEOUT
#  error "CONFIG_NETDB_DNSCLIENT_SEND_TIMEOUT is required"
#endif
#ifndef CONFIG_NETDB_DNSCLIENT_RECV_TIMEOUT
#  error "CONFIG_NETDB_DNSCLIENT_RECV_TIMEOUT is required"
#endif
#ifndef CONFIG_NETDB_DNSCLIENT_RETRIES
#  error "CONFIG_NETDB_DNSCLIENT_RETRIES is required"
#endif

#define VV_DNS_NUTTX_CALL_BOUND_MS \
  (1000u * (CONFIG_NETDB_DNSCLIENT_SEND_TIMEOUT + \
            CONFIG_NETDB_DNSCLIENT_RECV_TIMEOUT) * \
   CONFIG_NETDB_DNSCLIENT_RETRIES)

struct vv_dns_nuttx_context
{
  volatile const bool *cancel_flag;
};

static struct vv_dns_nuttx_context g_vv_dns_nuttx;

static uint64_t vv_dns_nuttx_now_ms(void *context)
{
  struct timespec value;
  (void)context;
  if (clock_gettime(CLOCK_MONOTONIC, &value) != 0)
    {
      return UINT64_MAX;
    }

  return (uint64_t)value.tv_sec * 1000u + (uint64_t)value.tv_nsec / 1000000u;
}

static void vv_dns_nuttx_sleep_ms(void *context, uint32_t delay_ms)
{
  (void)context;
  usleep((useconds_t)delay_ms * 1000u);
}

static bool vv_dns_nuttx_cancelled(void *context)
{
  struct vv_dns_nuttx_context *state = context;
  return state->cancel_flag != NULL && *state->cancel_flag;
}

static enum vv_dns_status vv_dns_nuttx_resolve(void *context,
                                                const char *hostname,
                                                uint32_t timeout_ms,
                                                uint32_t *ipv4_be,
                                                int *backend_code)
{
  struct addrinfo hints;
  struct addrinfo *addresses = NULL;
  struct addrinfo *cursor;
  int rc;
  (void)context;

  if (timeout_ms < VV_DNS_NUTTX_CALL_BOUND_MS)
    {
      return VV_DNS_DEADLINE_EXCEEDED;
    }

  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_INET;
  hints.ai_socktype = SOCK_STREAM;
  rc = getaddrinfo(hostname, NULL, &hints, &addresses);
  *backend_code = rc;
  if (rc != 0)
    {
      if (rc == EAI_AGAIN)
        {
          return VV_DNS_TEMPORARY_FAILURE;
        }

#ifdef EAI_NONAME
      if (rc == EAI_NONAME)
        {
          return VV_DNS_NOT_FOUND;
        }
#endif
#ifdef EAI_NODATA
      if (rc == EAI_NODATA)
        {
          return VV_DNS_NO_IPV4_ADDRESS;
        }
#endif
      return VV_DNS_SYSTEM_FAILURE;
    }

  for (cursor = addresses; cursor != NULL; cursor = cursor->ai_next)
    {
      if (cursor->ai_family == AF_INET &&
          cursor->ai_addrlen >= sizeof(struct sockaddr_in))
        {
          const struct sockaddr_in *address =
            (const struct sockaddr_in *)cursor->ai_addr;
          *ipv4_be = address->sin_addr.s_addr;
          freeaddrinfo(addresses);
          return *ipv4_be != 0 ? VV_DNS_OK : VV_DNS_NO_IPV4_ADDRESS;
        }
    }

  freeaddrinfo(addresses);
  return VV_DNS_NO_IPV4_ADDRESS;
}

int vv_dns_nuttx_backend_init(struct vv_dns_backend *backend,
                              volatile const bool *cancel_flag)
{
  if (backend == NULL)
    {
      return -EINVAL;
    }

  g_vv_dns_nuttx.cancel_flag = cancel_flag;
  memset(backend, 0, sizeof(*backend));
  backend->context = &g_vv_dns_nuttx;
  backend->resolve_ipv4 = vv_dns_nuttx_resolve;
  backend->now_ms = vv_dns_nuttx_now_ms;
  backend->sleep_ms = vv_dns_nuttx_sleep_ms;
  backend->cancelled = vv_dns_nuttx_cancelled;
  return 0;
}

